// 由 tools/build_vboard.py 產生，不要手改；來源 vboard/py/
export const PY_FILES = {
 "_vboard.py": "\"\"\"虛擬板執行器（Python 端）：建立 lab.display、執行學生程式、把例外整理成和實機一樣的 traceback。\"\"\"\nimport sys\nimport io\nimport lab\nimport labjs as _js\n\n\ndef setup(board):\n    lab.board = board\n    from lab import board_tqt\n    if board == \"tqt_pro\":\n        lab.display = board_tqt.Display()\n    else:\n        lab.display = board_tqt.DummyDisplay()\n    lab._stop = False\n    lab._cmd_handler = None\n    del lab._cmd_queue[:]\n    lab._pins.clear()\n\n\ndef check(code, name=\"main.py\"):\n    \"\"\"語法檢查：回 JSON 字串 {\"ok\",\"line\",\"msg\"}，與板子 /check 同格式。\"\"\"\n    import json\n    try:\n        compile(code, name, \"exec\")\n        return json.dumps({\"ok\": True, \"line\": None, \"msg\": \"ok\"})\n    except SyntaxError as e:\n        buf = io.StringIO()\n        sys.print_exception(e, buf)\n        txt = buf.getvalue()\n        line = None\n        for l in txt.split(\"\\n\"):\n            if (\"File \\\"%s\\\"\" % name) in l and \"line \" in l:\n                try:\n                    line = int(l.split(\"line \")[1].split(\",\")[0].split()[0])\n                except Exception:\n                    pass\n        msg = txt.strip().split(\"\\n\")[-1]\n        return json.dumps({\"ok\": False, \"line\": line, \"msg\": msg})\n\n\ndef print_exception(e, name=\"main.py\"):\n    buf = io.StringIO()\n    sys.print_exception(e, buf)\n    lines = []\n    for l in buf.getvalue().split(\"\\n\"):\n        if \"<stdin>\" in l or \"_vboard.py\" in l:\n            continue\n        lines.append(l)\n    return \"\\n\".join(lines).strip() + \"\\n\"\n\n\ndef clear_main(g):\n    \"\"\"清掉上一次執行留下的全域變數（學生程式在 runPython 的全域命名空間執行，由 JS 傳 globals() 進來）。\"\"\"\n    for k in list(g.keys()):\n        if k not in (\"__name__\", \"__builtins__\", \"__file__\", \"_vboard\", \"lab\", \"sys\"):\n            del g[k]\n    g[\"lab\"] = lab\n\n\ndef begin(name=\"main.py\"):\n    import time\n    lab._stop = False\n    lab._last_yield = time.ticks_ms()\n    _js.emit('{\"t\":\"start\",\"file\":\"%s\"}' % name)\n\n\ndef format_error(txt, name=\"main.py\"):\n    \"\"\"把 runPythonAsync 丟出的 traceback 整理成和實機一樣：<stdin> → 檔名，去掉執行器的框架。\"\"\"\n    out = []\n    for l in txt.split(\"\\n\"):\n        if \"_vboard.py\" in l or \"lab/__init__.py\" in l or \"micropython.mjs\" in l or l.strip().startswith(\"at \"):\n            continue\n        out.append(l.replace('\"<stdin>\"', '\"%s\"' % name))\n    return \"\\n\".join(out).strip() + \"\\n\"\n",
 "lab/__init__.py": "\"\"\"lab（虛擬板版）：和板子上的 lab 同一組 API，但在瀏覽器的 MicroPython（WebAssembly）裡執行。\n\n差異：lab.sleep 由執行器改寫成 `await lab.sleep(...)`（頂層與含它的函式都會自動變 async），\n畫面、LED、腳位、感測值全部透過 labjs（JS 替身）送到虛擬板畫面。\n\"\"\"\nimport time as _time\nimport json as _json\nimport labjs as _js\n\n__version__ = \"0.5.1-virtual\"\n\n\nclass StopRequested(Exception):\n    \"\"\"停止鍵按下後，lab.sleep() 會丟出這個例外來結束程式。\"\"\"\n    pass\n\n\n_stop = False\n_cmd_handler = None\n_cmd_queue = []\ndisplay = None            # 由 _vboard.setup() 依板型設定\nboard = \"tqt_pro\"\n_pins = {}\n_last_yield = 0\n_pending = []            # on_cmd 處理函式若含 lab.sleep 會變成 async，回傳的協程排到這裡，在 lab.sleep 裡 await\ncamera = None\n\n\ndef _emit(t, **kw):\n    kw[\"t\"] = t\n    _js.emit(_json.dumps(kw))\n\n\ndef emit(t, **kw):\n    _emit(t, **kw)\n\n\ndef _push_cmd(js_str):\n    \"\"\"JS 送進來的遙控／視覺指令（JSON 字串）先排隊，等學生程式呼叫 lab.sleep／lab.running 時處理。\"\"\"\n    try:\n        cmd = _json.loads(js_str)\n    except Exception:\n        return\n    if cmd.get(\"op\") == \"led\" and not _cmd_handler:\n        led(cmd.get(\"v\")); return\n    _cmd_queue.append(cmd)\n    if len(_cmd_queue) > 50:\n        del _cmd_queue[:25]\n\n\ndef _drain_cmds():\n    while _cmd_queue:\n        cmd = _cmd_queue.pop(0)\n        if cmd.get(\"op\") == \"led\" and cmd.get(\"_builtin\"):\n            led(cmd.get(\"v\")); continue\n        if _cmd_handler:\n            try:\n                r = _cmd_handler(cmd)\n                if r is not None and hasattr(r, \"send\") and hasattr(r, \"close\"):\n                    _pending.append(r)\n            except StopRequested:\n                raise\n            except Exception as e:\n                _emit(\"err\", s=\"on_cmd 處理錯誤：%r\\n\" % e)\n\n\ndef running():\n    \"\"\"停止鍵按下後變 False。虛擬板：迴圈超過 3 秒都沒有 lab.sleep 會自動停（瀏覽器畫面會卡住）。\"\"\"\n    _drain_cmds()\n    if _stop:\n        return False\n    if _time.ticks_diff(_time.ticks_ms(), _last_yield) > 3000:\n        _emit(\"err\", s=\"虛擬板：迴圈裡超過 3 秒沒有 lab.sleep()，畫面會卡住，已自動停止。請在 while lab.running(): 裡加 lab.sleep(0.05)。\\n\")\n        raise StopRequested()\n    return True\n\n\nasync def sleep(seconds):\n    \"\"\"像 time.sleep，但會讓瀏覽器畫面更新，並處理排隊中的指令；停止時丟 StopRequested。\"\"\"\n    global _last_yield\n    _drain_cmds()\n    while _pending:\n        await _pending.pop(0)\n    if _stop:\n        raise StopRequested()\n    ms = int(seconds * 1000)\n    end = _time.ticks_add(_time.ticks_ms(), ms)\n    while True:\n        left = _time.ticks_diff(end, _time.ticks_ms())\n        await _js.sleep(min(50, max(0, left)))\n        _last_yield = _time.ticks_ms()\n        _drain_cmds()\n        if _stop:\n            raise StopRequested()\n        if left <= 50:\n            break\n\n\nasync def sleep_ms(ms):\n    await sleep(ms / 1000)\n\n\ndef log(*args):\n    s = \" \".join(str(a) for a in args)\n    print(s)\n\n\ndef send(**values):\n    \"\"\"把感測值送到主控台／感測值列：lab.send(temp=25.3)\"\"\"\n    _emit(\"sensor\", v=values)\n\n\ndef on_cmd(fn):\n    global _cmd_handler\n    _cmd_handler = fn\n    return fn\n\n\ndef rssi():\n    \"\"\"虛擬 Wi-Fi 訊號（由虛擬板滑桿設定，預設 -55 dBm）。\"\"\"\n    return _js.rssi()\n\n\ndef battery():\n    \"\"\"虛擬電池電壓（由虛擬板滑桿設定）。\"\"\"\n    if board != \"tqt_pro\":\n        return None\n    return _js.battery()\n\n\ndef pin(n, mode=\"out\"):\n    from machine import Pin\n    key = (n, mode)\n    if key not in _pins:\n        _pins[key] = Pin(n, Pin.OUT if mode == \"out\" else Pin.IN)\n    return _pins[key]\n\n\ndef led(v):\n    \"\"\"板載 LED：T-QT Pro 沒有 LED → 亮螢幕右上角小方塊（和實機一樣）＋虛擬板角落的 LED。\"\"\"\n    _js.led(1 if v else 0)\n    if board == \"tqt_pro\" and display is not None and hasattr(display, \"buf\"):\n        display.fill_rect(120, 0, 8, 8, display.WHITE if v else display.BLACK)\n        display.show()\n",
 "lab/board_tqt.py": "\"\"\"T-QT Pro 128×128 螢幕（虛擬板版）：同一份 framebuf 畫法，show() 把 RGB565 緩衝交給 JS 畫到 canvas。\"\"\"\nimport framebuf\nimport labjs as _js\n\nW = H = 128\n\n\ndef color(r, g, b):\n    \"\"\"RGB888 → 面板用的 RGB565（已交換位元組，可直接給 framebuf）——與實機完全相同。\"\"\"\n    c = ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)\n    return ((c & 0xFF) << 8) | (c >> 8)\n\n\nclass Display(framebuf.FrameBuffer):\n    BLACK = 0\n    WHITE = 0xFFFF\n    RED = color(255, 0, 0)\n    GREEN = color(0, 255, 0)\n    BLUE = color(0, 0, 255)\n    YELLOW = color(255, 255, 0)\n    CYAN = color(0, 255, 255)\n\n    def __init__(self):\n        self.buf = bytearray(W * H * 2)\n        super().__init__(self.buf, W, H, framebuf.RGB565)\n        self.fill(0)\n        self.show()\n\n    def show(self):\n        f = open(\"/screen.bin\", \"wb\")\n        f.write(self.buf)\n        f.close()\n        _js.show()\n\n    def backlight(self, on=True):\n        pass\n\n    def print_lines(self, lines, fg=0xFFFF, bg=0):\n        self.fill(bg)\n        for i, line in enumerate(lines[:16]):\n            self.text(str(line)[:16], 0, i * 8, fg)\n        self.show()\n\n\nclass DummyDisplay:\n    \"\"\"沒有螢幕的板子：text() 只記錄到主控台（與實機 DummyDisplay 相同）。\"\"\"\n    BLACK = 0; WHITE = 1; RED = 2; GREEN = 3; BLUE = 4; YELLOW = 5; CYAN = 6\n\n    def __init__(self):\n        self.lines = []\n\n    def fill(self, c): self.lines = []\n    def fill_rect(self, *a): pass\n    def pixel(self, *a): pass\n    def rect(self, *a): pass\n    def line(self, *a): pass\n    def hline(self, *a): pass\n    def vline(self, *a): pass\n\n    def text(self, s, x=0, y=0, c=1):\n        self.lines.append(s)\n\n    def show(self):\n        import lab\n        if self.lines:\n            lab.emit(\"display\", lines=self.lines[:])\n\n    def print_lines(self, lines, *a):\n        self.lines = list(lines); self.show()\n\n    def backlight(self, on=True): pass\n",
 "lab/boards.py": "\"\"\"板型表（虛擬板子集）：只有 lab.led 與保護檢查用到的欄位。\"\"\"\nLED_PIN = {\"tqt_pro\": None, \"devkit\": 2, \"generic\": 2}\nLED_INVERTED = {\"tqt_pro\": False, \"devkit\": False, \"generic\": False}\nBUTTONS = {\"tqt_pro\": [0, 47], \"devkit\": [0]}\nHAS_DISPLAY = {\"tqt_pro\": True, \"devkit\": False, \"generic\": False}\n",
 "machine.py": "\"\"\"machine（虛擬板替身）：Pin／PWM／ADC 的狀態都交給 JS 畫在板子上；reset 重開虛擬板。\"\"\"\nimport labjs as _js\n\n\nclass Pin:\n    IN = 0\n    OUT = 1\n    OPEN_DRAIN = 2\n    PULL_UP = 1\n    PULL_DOWN = 2\n    IRQ_RISING = 1\n    IRQ_FALLING = 2\n\n    def __init__(self, id, mode=-1, pull=-1, value=None, **kw):\n        self.id = int(id)\n        self.mode = mode\n        self.pull = pull\n        self._v = 0\n        if value is not None:\n            self.value(value)\n        _js.pin_mode(self.id, \"out\" if mode == Pin.OUT else \"in\", 1 if pull == Pin.PULL_UP else 0)\n\n    def init(self, mode=-1, pull=-1, **kw):\n        self.mode = mode; self.pull = pull\n\n    def value(self, v=None):\n        if v is None:\n            if self.mode == Pin.OUT:\n                return self._v\n            return int(_js.pin_read(self.id))\n        self._v = 1 if v else 0\n        _js.pin_write(self.id, self._v)\n\n    def on(self): self.value(1)\n    def off(self): self.value(0)\n    def __call__(self, v=None): return self.value(v)\n\n    def irq(self, handler=None, trigger=3, **kw):\n        _js.pin_irq(self.id, handler, trigger)\n        return self\n\n\nclass PWM:\n    def __init__(self, pin, freq=5000, duty=None, duty_u16=None, duty_ns=None, **kw):\n        self.pin = pin if isinstance(pin, int) else pin.id\n        self._freq = freq\n        self._duty16 = 0\n        if duty is not None: self.duty(duty)\n        if duty_u16 is not None: self.duty_u16(duty_u16)\n        if duty_ns is not None: self.duty_ns(duty_ns)\n\n    def freq(self, f=None):\n        if f is None: return self._freq\n        self._freq = f; self._report()\n\n    def duty(self, d=None):\n        if d is None: return self._duty16 * 1023 // 65535\n        self._duty16 = int(d) * 65535 // 1023; self._report()\n\n    def duty_u16(self, d=None):\n        if d is None: return self._duty16\n        self._duty16 = int(d); self._report()\n\n    def duty_ns(self, ns=None):\n        period_ns = 1_000_000_000 // max(1, self._freq)\n        if ns is None: return self._duty16 * period_ns // 65535\n        self._duty16 = int(ns) * 65535 // period_ns; self._report()\n\n    def deinit(self):\n        _js.pwm(self.pin, 0, 0)\n\n    def _report(self):\n        _js.pwm(self.pin, self._freq, self._duty16)\n\n\nclass ADC:\n    ATTN_0DB = 0; ATTN_2_5DB = 1; ATTN_6DB = 2; ATTN_11DB = 3\n    WIDTH_12BIT = 12\n\n    def __init__(self, pin, atten=3, **kw):\n        self.pin = pin if isinstance(pin, int) else pin.id\n        _js.adc_init(self.pin)\n\n    def atten(self, a): pass\n    def width(self, w): pass\n\n    def read(self):\n        return int(_js.adc_read(self.pin))\n\n    def read_u16(self):\n        return int(_js.adc_read(self.pin)) * 65535 // 4095\n\n    def read_uv(self):\n        return int(_js.adc_read(self.pin)) * 3300000 // 4095\n\n\nclass RTC:\n    def datetime(self, *a):\n        import time\n        t = time.localtime()\n        return (t[0], t[1], t[2], t[6], t[3], t[4], t[5], 0)\n\n\ndef reset():\n    _js.reset()\n    raise SystemExit()\n\n\ndef soft_reset():\n    reset()\n\n\ndef freq(*a):\n    return 240_000_000\n\n\ndef unique_id():\n    return b\"\\x24\\xec\\x4a\\x00\\x7f\\x2a\"\n\n\ndef idle(): pass\n\n\nclass WDT:\n    def __init__(self, *a, **k): pass\n    def feed(self): pass\n",
 "network.py": "\"\"\"network（虛擬板替身）：永遠「已連上」一個假的 Wi-Fi，訊號強度由虛擬板滑桿決定；不能真的連網。\"\"\"\nimport labjs as _js\n\nSTA_IF = 0\nAP_IF = 1\nSTAT_GOT_IP = 1010\n\n\nclass WLAN:\n    def __init__(self, mode=STA_IF):\n        self.mode = mode\n        self._active = True\n\n    def active(self, v=None):\n        if v is None: return self._active\n        self._active = bool(v)\n\n    def isconnected(self):\n        return self.mode == STA_IF\n\n    def connect(self, *a, **k):\n        pass\n\n    def disconnect(self):\n        pass\n\n    def status(self, key=None):\n        if key == \"rssi\":\n            return int(_js.rssi())\n        return STAT_GOT_IP\n\n    def ifconfig(self, *a):\n        return (\"192.168.4.2\", \"255.255.255.0\", \"192.168.4.1\", \"192.168.4.1\")\n\n    def config(self, key=None, **kw):\n        if key == \"essid\" or key == \"ssid\": return \"虛擬板\"\n        if key == \"mac\": return b\"\\x24\\xec\\x4a\\x00\\x7f\\x2a\"\n        return None\n\n    def scan(self):\n        return [(b\"ESP32LAB-virtual\", b\"\\x24\\xec\\x4a\\x00\\x7f\\x2a\", 6, int(_js.rssi()), 3, False)]\n\n\ndef hostname(name=None):\n    return \"esp32lab-virtual\"\n",
 "ntptime.py": "\"\"\"ntptime（虛擬板替身）：瀏覽器的時間就是對的，settime() 什麼都不用做。\"\"\"\nhost = \"pool.ntp.org\"\ntimeout = 1\n\n\ndef time():\n    import time as _t\n    return int(_t.time())\n\n\ndef settime():\n    pass\n"
};
